diff --git a/scripts/check-gemini-store.mjs b/scripts/check-gemini-store.mjs
new file mode 100644
index 0000000..1db986a
--- /dev/null
+++ b/scripts/check-gemini-store.mjs
@@ -0,0 +1,7 @@
+import fs from 'node:fs';
+const src = fs.readFileSync(new URL('../app/api/chat/route.ts', import.meta.url), 'utf8');
+if (!/extraBody:\s*\{\s*store:\s*false\s*\}/.test(src)) {
+  console.error('chat route does not send store:false');
+  process.exit(1);
+}
+console.log('ok');

