new file mode 100644
index 0000000..31b0cbb
--- /dev/null
+++ b/scripts/check-live-model.mjs
@@ -0,0 +1,5 @@
+import { readFileSync } from 'node:fs';
+const s = readFileSync('lib/gemini-tools.ts', 'utf8');
